// Package spec holds the New API route table and the parser that derives it
// from upstream router source.
//
// The table is the contract between this server and a New API release. It is
// regenerated by cmd/routesync from the exact git tag of the running instance,
// so "which endpoints exist" is never a guess.
package spec

import (
	"sort"
	"strings"
)

// Route is one registered (method, path) pair on the admin surface.
type Route struct {
	Method string `json:"method"`
	Path   string `json:"path"`
	// Group is the first path segment after /api, e.g. "channel".
	Group  string `json:"group"`
	Source string `json:"source,omitempty"`
}

// Key is the comparable identity of a route.
//
// Gin registers "/api/channel" and "/api/channel/" as distinct paths, so the
// table preserves exactly what upstream declares. Comparison ignores the
// trailing slash because New API is not consistent about which form it uses.
func (r Route) Key() string { return r.Method + " " + CanonicalPath(r.Path) }

// CanonicalPath strips a trailing slash, except for the root.
func CanonicalPath(p string) string {
	if len(p) > 1 {
		return strings.TrimSuffix(p, "/")
	}
	return p
}

// GroupOf derives the grouping bucket for a path.
func GroupOf(path string) string {
	trimmed := strings.TrimPrefix(path, "/api")
	trimmed = strings.TrimPrefix(trimmed, "/")
	if trimmed == "" {
		return "root"
	}
	if i := strings.IndexByte(trimmed, '/'); i >= 0 {
		trimmed = trimmed[:i]
	}
	return trimmed
}

// Filter returns the routes whose path starts with prefix.
func Filter(routes []Route, prefix string) []Route {
	out := make([]Route, 0, len(routes))
	for _, r := range routes {
		if strings.HasPrefix(r.Path, prefix) {
			out = append(out, r)
		}
	}
	return out
}

// Index maps a route key to the route.
func Index(routes []Route) map[string]Route {
	m := make(map[string]Route, len(routes))
	for _, r := range routes {
		m[r.Key()] = r
	}
	return m
}

// Diff reports which routes exist upstream but not locally (missing), and which
// exist locally but no longer exist upstream (stale).
func Diff(local, upstream []Route) (missing, stale []Route) {
	have := Index(local)
	want := Index(upstream)
	for k, r := range want {
		if _, ok := have[k]; !ok {
			missing = append(missing, r)
		}
	}
	for k, r := range have {
		if _, ok := want[k]; !ok {
			stale = append(stale, r)
		}
	}
	sortRoutes(missing)
	sortRoutes(stale)
	return missing, stale
}

// Sort orders routes by path then method for stable output.
func SortRoutes(routes []Route) { sortRoutes(routes) }

func sortRoutes(routes []Route) {
	sort.Slice(routes, func(i, j int) bool {
		if routes[i].Path != routes[j].Path {
			return routes[i].Path < routes[j].Path
		}
		return routes[i].Method < routes[j].Method
	})
}
